// splitFileName returns a name, version, release, epoch, arch:
//
//	e.g.
//		foo-1.0-1.i386.rpm => foo, 1.0, 1, i386
//		1:bar-9-123a.ia64.rpm => bar, 9, 123a, 1, ia64
//
// https://github.com/rpm-software-management/yum/blob/043e869b08126c1b24e392f809c9f6871344c60d/rpmUtils/miscutils.py#L301
func splitFileName(filename string) (name, ver, rel, epoch, arch string, err error) {
	invalid := func() (string, string, string, string, string, error) {
		return "", "", "", "", "", xerrors.Errorf("unexpected file name. expected: %q, actual: %q", "<name>-<version>-<release>.<arch>.rpm", filename)
	}
	if !strings.HasSuffix(filename, ".rpm") {
		return invalid()
	}
	basename := strings.TrimSuffix(filename, ".rpm")

	archIndex := strings.LastIndex(basename, ".")
	if strings.HasSuffix(basename, "-src") {
		archIndex = len(basename) - len("-src")
	}
	if archIndex < 0 || archIndex == len(basename)-1 {
		return invalid()
	}
	arch = basename[archIndex+1:]
	if strings.ContainsAny(arch, ".-/:") {
		return invalid()
	}

	relIndex := strings.LastIndex(basename[:archIndex], "-")
	if relIndex == -1 {
		return invalid()
	}
	rel = basename[relIndex+1 : archIndex]

	verIndex := strings.LastIndex(basename[:relIndex], "-")
	if verIndex == -1 {
		return invalid()
	}
	// In the -src spelling the release can contain hyphens. Choose the
	// rightmost numeric version after a name component and retain the rest
	// as the release.
	if basename[archIndex] == '-' {
		parts := strings.Split(basename[:archIndex], "-")
		for i := len(parts) - 2; i > 0; i-- {
			if parts[i] != "" && parts[i][0] >= '0' && parts[i][0] <= '9' && (parts[i-1] == "" || parts[i-1][0] < '0' || parts[i-1][0] > '9') {
				verIndex = len(strings.Join(parts[:i], "-"))
				relIndex = verIndex + 1 + len(parts[i])
				break
			}
		}
	}
	ver = basename[verIndex+1 : relIndex]
	rel = basename[relIndex+1 : archIndex]

	epochIndex := strings.Index(basename, ":")
	if epochIndex != -1 {
		epoch = basename[:epochIndex]
	}

	name = basename[epochIndex+1 : verIndex]
	if name == "" || ver == "" || (rel == "" && arch != "src") || strings.ContainsAny(name, " /\t\n") || strings.ContainsAny(ver, " /\t\n:") || strings.ContainsAny(rel, " /\t\n:") || (epochIndex != -1 && (epoch == "" || strings.ContainsAny(epoch, " /\t\n-"))) {
		return invalid()
	}
	return name, ver, rel, epoch, arch, nil
}

